import{_ as t,o,c as r,ag as a}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Creational Design Patterns — Learning Guide","description":"","frontmatter":{},"headers":[],"relativePath":"design_patterns/creational/CreationalPatternsRoadmap.md","filePath":"design_patterns/creational/CreationalPatternsRoadmap.md"}'),i={name:"design_patterns/creational/CreationalPatternsRoadmap.md"};function d(n,e,c,s,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="creational-design-patterns-—-learning-guide" tabindex="-1">Creational Design Patterns — Learning Guide <a class="header-anchor" href="#creational-design-patterns-—-learning-guide" aria-label="Permalink to &quot;Creational Design Patterns — Learning Guide&quot;">​</a></h1><p>A reading sequence that builds naturally, front-loads the practically useful patterns, and slots in two non-GoF side quests at the right moment. Follow this order if you&#39;re learning from scratch; jump to any section if you already know some of them.</p><hr><h2 id="recommended-sequence" tabindex="-1">Recommended sequence <a class="header-anchor" href="#recommended-sequence" aria-label="Permalink to &quot;Recommended sequence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Singleton  →  Factory Method  →  Builder  →  Side quest A  →  Abstract Factory  →  [Side quest B]  →  Prototype</span></span></code></pre></div><p>Each step below tells you what to read, what to try, and why it comes where it does.</p><hr><h2 id="_1-singleton" tabindex="-1">1. Singleton <a class="header-anchor" href="#_1-singleton" aria-label="Permalink to &quot;1. Singleton&quot;">​</a></h2><p><strong>Read:</strong> <code>singleton/Singleton.md</code></p><p><strong>Run:</strong> <code>ThreadSafeSingleton.main</code> — races 50 threads; should always print PASS.</p><p><strong>Try yourself:</strong> Implement all five variants from scratch (no singleton, eager, lazy, thread-safe, Bill Pugh). Then answer: why is <code>BillPughSingleton</code> preferred over <code>ThreadSafeSingleton</code>?</p><p><strong>Why first:</strong> Simplest creational pattern. Introduces the idea that construction can be controlled — which all the others build on.</p><hr><h2 id="_2-factory-method" tabindex="-1">2. Factory Method <a class="header-anchor" href="#_2-factory-method" aria-label="Permalink to &quot;2. Factory Method&quot;">​</a></h2><p><strong>Read:</strong> <code>factory/Factory.md</code> — overview of Simple Factory vs GoF Factory Method and when to promote one to the other.</p><p>Then the pattern-specific docs in order:</p><ol><li><code>factory/simple_factory/SimpleFactory.md</code> — the non-GoF starting point</li><li><code>factory/factory_method_basic/FactoryMethodBasic.md</code> — learning variant (static services, no interface above the abstract class)</li><li><code>factory/factory_method/FactoryMethodProd.md</code> — production variant (injected services, <code>HiringProcess</code> interface, DIP-clean <code>HR</code>)</li></ol><p><strong>Run:</strong> <code>simple_factory/SimpleFactoryRun</code>, <code>factory_method_basic/FactoryMethodRun</code>, <code>factory_method/FactoryMethodRun</code> — compare the wiring cost across the three.</p><p><strong>Try yourself:</strong> Build a <code>NotificationFactory</code> with <code>EmailNotification</code> and <code>SmsNotification</code>. Make the caller (<code>NotificationSender</code>) depend only on the <code>Notification</code> interface, not on either concrete class.</p><p><strong>Why here:</strong> Introduces polymorphic creation — the concept that powers Abstract Factory and most DI containers.</p><hr><h2 id="side-quest-a-—-static-factory-methods-effective-java-item-1" tabindex="-1">Side quest A — Static factory methods (Effective Java Item 1) <a class="header-anchor" href="#side-quest-a-—-static-factory-methods-effective-java-item-1" aria-label="Permalink to &quot;Side quest A — Static factory methods (Effective Java Item 1)&quot;">​</a></h2><p><strong>Read:</strong> <code>static_factory_methods/StaticFactoryMethods.md</code></p><p><strong>Run:</strong> <code>static_factory_methods/TemperatureRun</code></p><p><strong>Why here:</strong> Takes ~20 minutes, pays off forever. Explains why <code>Integer.valueOf(5)</code> beats <code>new Integer(5)</code>, why <code>List.of(...)</code> looks the way it does, and how <code>JobOffer.builder()</code> differs from a true static factory method. Sets up the mental model for Spring <code>@Bean</code> methods.</p><hr><h2 id="_3-builder" tabindex="-1">3. Builder <a class="header-anchor" href="#_3-builder" aria-label="Permalink to &quot;3. Builder&quot;">​</a></h2><p><strong>Read:</strong> <code>builder/Builder.md</code> — overview of the four variants.</p><p>Then the variant-specific docs in order:</p><ol><li><code>builder/simple_builder/BuilderBasic.md</code> — hand-written EJ-style (required fields in constructor, validation in <code>build()</code>)</li><li><code>builder/lombok_builder/BuilderLombok.md</code> — what <code>@Builder</code> generates and what it costs you</li><li><code>builder/director_builder/BuilderDirector.md</code> — Director as a recipe holder; never calls <code>build()</code></li><li><code>builder/director_builder_gof/BuilderDirectorGof.md</code> — GoF Director: same recipe drives multiple builders, different artefacts</li></ol><p><strong>Run:</strong> All four <code>JobOfferRun</code> mains. The GoF one is the most instructive — notice how one recipe produces a <code>JobOffer</code> from one builder and a <code>String</code> letter from another.</p><p><strong>Try yourself:</strong> Model a <code>Pizza</code> with a required size and optional toppings. First in plain Java (required fields in builder constructor, validation in <code>build()</code>), then with <code>@Builder</code>. Notice what <code>@Builder</code> cannot enforce.</p><p><strong>Why here:</strong> The most practically useful creational pattern. You will use it constantly in real Java code.</p><hr><h2 id="side-quest-b-—-dependency-injection" tabindex="-1">Side quest B — Dependency Injection <a class="header-anchor" href="#side-quest-b-—-dependency-injection" aria-label="Permalink to &quot;Side quest B — Dependency Injection&quot;">​</a></h2><p><strong>Read:</strong> <code>todo/FoundationsToRead.md</code> → &quot;DI in practice&quot;</p><p><strong>Why here:</strong> Once Factory Method clicks, DI is the natural next question — <em>what if something else held my object graph and handed me my collaborators?</em> Doing this detour makes Abstract Factory feel motivated rather than theoretical.</p><p><strong>Three passes:</strong> manual DI (constructor injection, wired in <code>main</code>) → Spring basics (<code>@Component</code>, <code>@Autowired</code>, <code>@Bean</code>) → bean scopes (singleton vs prototype vs request).</p><p><strong>Try yourself:</strong> Refactor the <code>NotificationFactory</code> from the Factory Method exercise so Spring injects the right implementation based on configuration. You should end up deleting the factory class entirely.</p><hr><h2 id="_4-abstract-factory" tabindex="-1">4. Abstract Factory <a class="header-anchor" href="#_4-abstract-factory" aria-label="Permalink to &quot;4. Abstract Factory&quot;">​</a></h2><p><strong>Read:</strong> <code>abstract_factory/AbstractFactory.md</code></p><p><strong>Run:</strong> <code>abstract_factory/RunAbstractFactory</code></p><p><strong>Try yourself:</strong> Build a <code>UIFactory</code> with <code>LightThemeFactory</code> and <code>DarkThemeFactory</code>. Each produces matching <code>Button</code>, <code>TextField</code>, and <code>Checkbox</code>. Write a <code>renderUI(UIFactory)</code> helper on the client side — not on the factory.</p><p><strong>Why here:</strong> Abstract Factory only makes sense once plain Factory Method is solid. The pattern is Factory Method scaled to a coordinated family of products.</p><p><strong>Key decision to think through:</strong> When does a set of objects qualify as a &quot;family&quot;? (Answer: when mixing products from different families would produce incorrect behaviour — e.g., a luxury chair with a cheap sofa breaks the design guarantee.)</p><hr><h2 id="_5-prototype" tabindex="-1">5. Prototype <a class="header-anchor" href="#_5-prototype" aria-label="Permalink to &quot;5. Prototype&quot;">​</a></h2><p><strong>Read:</strong> <code>prototype/Prototype.md</code> (once written)</p><p><strong>Try yourself:</strong> Implement a <code>Shape</code> with a <code>List&lt;Point&gt;</code> both ways:</p><ol><li><code>Cloneable</code> + <code>clone()</code> — observe the shallow-copy trap (both copies share the same list).</li><li>Copy constructor — proper deep copy with no shared state.</li></ol><p>Form your own opinion on which is safer and clearer to read.</p><p><strong>Why last:</strong> Least used in modern Java. The GoF mechanics (<code>Cloneable</code>/<code>clone()</code>) are widely considered broken; copy constructors or serialization libraries win in practice. Worth knowing for interviews and for recognising the pattern when you see it.</p><hr><h2 id="side-quest-b-revisit-—-di-orchestration-mini-project" tabindex="-1">Side quest B revisit — DI orchestration mini-project <a class="header-anchor" href="#side-quest-b-revisit-—-di-orchestration-mini-project" aria-label="Permalink to &quot;Side quest B revisit — DI orchestration mini-project&quot;">​</a></h2><p><strong>Read:</strong> <code>todo/study_plan/deep_dives/PatternSelectionExercise.md</code></p><p>Practice choosing between Strategy, Registry, and Spring DI to orchestrate multiple factories from a single client. This is the synthesis exercise — it forces you to pick between patterns rather than just implement them.</p><hr><h2 id="completion-criteria" tabindex="-1">Completion criteria <a class="header-anchor" href="#completion-criteria" aria-label="Permalink to &quot;Completion criteria&quot;">​</a></h2><p>You can move on from any pattern when you can answer these without looking them up:</p><ol><li>What problem does this pattern solve? (one sentence)</li><li>What does the minimum implementation look like? (can you write it from scratch?)</li><li>Where does it appear in the JDK or a popular library?</li><li>When would you <em>not</em> use it?</li><li>How does it interact with dependency injection?</li></ol><hr><h2 id="if-you-only-have-time-for-the-essentials" tabindex="-1">If you only have time for the essentials <a class="header-anchor" href="#if-you-only-have-time-for-the-essentials" aria-label="Permalink to &quot;If you only have time for the essentials&quot;">​</a></h2><p><strong>Singleton + Factory Method + Builder</strong> cover roughly 90 % of creational code in real Java projects. Add Side quest A (static factory methods) for another 20 minutes that pays off in every codebase you read.</p><p>Abstract Factory earns its keep when you interview or when you encounter JDBC / UI toolkits. Prototype is mostly for interview prep and recognising the shape in libraries.</p><hr><h2 id="all-docs-at-a-glance" tabindex="-1">All docs at a glance <a class="header-anchor" href="#all-docs-at-a-glance" aria-label="Permalink to &quot;All docs at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>Overview doc</th><th>Variant / detail docs</th></tr></thead><tbody><tr><td>Singleton</td><td><code>singleton/Singleton.md</code></td><td>—</td></tr><tr><td>Factory Method</td><td><code>factory/Factory.md</code></td><td><code>simple_factory/SimpleFactory.md</code>, <code>factory_method_basic/FactoryMethodBasic.md</code>, <code>factory_method/FactoryMethodProd.md</code></td></tr><tr><td>Builder</td><td><code>builder/Builder.md</code></td><td><code>simple_builder/BuilderBasic.md</code>, <code>lombok_builder/BuilderLombok.md</code>, <code>director_builder/BuilderDirector.md</code>, <code>director_builder_gof/BuilderDirectorGof.md</code></td></tr><tr><td>Static factory methods</td><td><code>static_factory_methods/StaticFactoryMethods.md</code></td><td>—</td></tr><tr><td>Abstract Factory</td><td><code>abstract_factory/AbstractFactory.md</code></td><td>—</td></tr><tr><td>Prototype</td><td><code>prototype/Prototype.md</code></td><td>—</td></tr></tbody></table><p><strong>Foundations and cross-cutting:</strong></p><ul><li><code>design_patterns/foundations/</code> — SOLID, supporting principles, OOP pillars, coupling/cohesion/smells, DIP vs DI</li><li><code>todo/study_plan/deep_dives/DesignThinkingProcess.md</code> — pattern-agnostic design heuristics (6-step process)</li><li><code>todo/study_plan/deep_dives/PatternSelectionExercise.md</code> — when to use which pattern, &quot;one HR, many factories&quot; orchestration exercise</li><li><code>todo/study_plan/deep_dives/PatternSelectionScenarios.md</code> — 25 production scenario exercises across the creational patterns</li></ul>',70)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
